"""Shared fixtures for the CPU tests. Fixture items are plumbing stand-ins generated by code;
they are never training data and never leave the temporary test directory."""
from __future__ import annotations

import json
import os
from pathlib import Path
from typing import List, Optional, Sequence, Tuple

import torch
from safetensors.torch import save_file

DEFAULT_TEST_MODEL = "Qwen/Qwen2.5-0.5B-Instruct"
QWEN_TARGETS = ["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"]


def synthetic_adapter(out_dir, shapes: Sequence[Tuple[str, int, int]], rank: int = 4, seed: int = 0,
                      dtype=torch.float32, extra_keys: Optional[dict] = None, std: float = 0.1) -> Path:
    """Write a PEFT-layout LoRA (adapter_config.json + adapter_model.safetensors) with random A and B."""
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    g = torch.Generator().manual_seed(seed)
    tensors = {}
    for prefix, out_f, in_f in shapes:
        tensors[f"{prefix}.lora_A.weight"] = (torch.randn(rank, in_f, generator=g) * std).to(dtype)
        tensors[f"{prefix}.lora_B.weight"] = (torch.randn(out_f, rank, generator=g) * std).to(dtype)
    for k, v in (extra_keys or {}).items():
        tensors[k] = v
    save_file(tensors, str(out_dir / "adapter_model.safetensors"), metadata={"format": "pt"})
    cfg = {"peft_type": "LORA", "r": rank, "lora_alpha": 2 * rank, "target_modules": ["q_proj"],
           "lora_dropout": 0.0, "bias": "none", "task_type": "CAUSAL_LM", "base_model_name_or_path": "synthetic"}
    (out_dir / "adapter_config.json").write_text(json.dumps(cfg, indent=2))
    return out_dir


def toy_shapes(layers: int = 2) -> List[Tuple[str, int, int]]:
    shapes = []
    for i in range(layers):
        root = f"base_model.model.model.layers.{i}"
        shapes += [(f"{root}.self_attn.q_proj", 24, 16), (f"{root}.self_attn.v_proj", 8, 16),
                   (f"{root}.mlp.down_proj", 16, 40)]
    return shapes


def tiny_model_path() -> Optional[str]:
    """Local path of the tiny Qwen model, or None when it is not available offline."""
    name = os.environ.get("ES_TEST_MODEL", DEFAULT_TEST_MODEL)
    if Path(name).exists():
        return name
    try:
        from huggingface_hub import try_to_load_from_cache
    except Exception:
        return None
    found = try_to_load_from_cache(name, "config.json")
    if isinstance(found, str):
        snap = Path(found).parent
        if (snap / "model.safetensors").exists() and (snap / "tokenizer_config.json").exists():
            return str(snap)
    return None


def qwen_random_lora(model_path: str, out_dir, rank: int = 4, seed: int = 0, std: float = 0.05) -> Path:
    """Save a random rank-`rank` PEFT LoRA on every language-model linear layer of a tiny Qwen."""
    from peft import LoraConfig, get_peft_model
    from transformers import AutoModelForCausalLM

    model = AutoModelForCausalLM.from_pretrained(model_path, dtype=torch.float32, local_files_only=True)
    cfg = LoraConfig(r=rank, lora_alpha=2 * rank, target_modules=QWEN_TARGETS, lora_dropout=0.0,
                     task_type="CAUSAL_LM")
    peft_model = get_peft_model(model, cfg)
    g = torch.Generator().manual_seed(seed)
    with torch.no_grad():
        for name, p in peft_model.named_parameters():
            if "lora_A" in name or "lora_B" in name:
                p.copy_(torch.randn(p.shape, generator=g) * std)
    out_dir = Path(out_dir)
    peft_model.save_pretrained(str(out_dir))
    return out_dir


def write_pairs(path, n_pairs: int, prefix: str = "p", split: str = "train_pool") -> Path:
    """Code-generated present/absent plumbing pairs in the yardstick v1 layout."""
    lines = []
    for i in range(n_pairs):
        group = f"ys1-{prefix}-{i:012x}"
        value = 100 + 7 * i
        for variant in ("present", "absent"):
            body = f"Record {i}. count: {value}." if variant == "present" else f"Record {i}. other: {value + 1}."
            lines.append({"id": f"{group}/{variant}", "group": group, "split": split, "variant": variant,
                          "prompt": body + " What is the count?", "answer_instruction": "End with ANSWER: <value>.",
                          "gold": {"kind": "value" if variant == "present" else "not_established",
                                   "value": str(value) if variant == "present" else None}})
    Path(path).write_text("".join(json.dumps(x, sort_keys=True) + "\n" for x in lines))
    return Path(path)


def write_retention(path, n: int) -> Path:
    lines = []
    for i in range(n):
        lines.append({"id": f"ret-{i:03d}", "split": "retention", "category": "utility",
                      "prompt": f"Reply with the number {i}.", "checks": {"any_of": [str(i)]}})
    Path(path).write_text("".join(json.dumps(x, sort_keys=True) + "\n" for x in lines))
    return Path(path)


def toy_grade(item: dict, reply: str) -> dict:
    """A tiny deterministic grader for loop plumbing with real models."""
    gold = (item.get("gold") or {}).get("value")
    if gold is None:
        ok = "not" in reply.lower()
    else:
        ok = gold in reply
    return {"verdict": "ok" if ok else "wrong", "correct": ok, "reward": 1.0 if ok else -0.5}
